    "parameters": [
      { "id": "tireRadius", "label": "Tire radius", "type": "Float", "min": 1.5, "max": 2.4, "step": 0.05, "default": 1.5, "hint": "outer radius of the tire, in cells (1 cell = 0.25 m)" },
      { "id": "rimRadius", "label": "Rim radius", "type": "Float", "min": 1.0, "max": 1.6, "step": 0.05, "default": 1.0, "hint": "radius of the rim disc, in cells; at most tire radius - 0.25" },
      { "id": "maxSteerDegrees", "label": "Max steer angle", "type": "Float", "min": 5, "max": 90, "step": 1, "default": 60, "hint": "wheel angle at steering signal +-1, degrees" },
      { "id": "steerRateDegrees", "label": "Steer speed", "type": "Float", "min": 30, "max": 720, "step": 10, "default": 180, "hint": "how fast the wheel turns to the commanded angle, degrees per second" },
      { "id": "reverse", "label": "Reverse", "type": "Bool", "default": false, "hint": "reverse the spin direction (a wheel on the other side of the axle)" }
    ]
